---SetWorldBossNodeInfo
---结算 世界 Boss 节点信息
function UIBattleEndWorldBoss:SetWorldBossNodeInfo()
    local showData = BattleEndMgr.showData
    if IsNull(showData) or (not isSet(showData, "response")) then return end
    local isOpen = true     -- 如果在战斗过程中活动结束了，结算请求的时候，服务器会返回err 999，直接在结算界面之前就踢人了。所以这里不会有活动结束的情况
    --- 节点激活状态
    KTool.SetActive(self.TxtNow.gameObject, isOpen)
    KTool.SetActive(self.TxtHistory.gameObject, isOpen)
    KTool.SetActive(self.TxtQuestLocked.gameObject, not isOpen) -- 活动结束提示
    if isOpen then
        if not isSet(showData, "response") then return end
        --- 分数文本组件赋值
        local dataResponse = showData.response
        local oldMyRankInfo = checkTable(dataResponse.oldMyRankInfo) -- 返回数据 历史
        local newMyRankInfo = checkTable(dataResponse.newMyRankInfo) -- 返回数据 当前
        --- 分数更新 Icon 提示
        local valueOld = math.modf(checkNumber(oldMyRankInfo.hurt))
        local valueNew = math.modf(checkNumber(newMyRankInfo.hurt))
        self.TxtNumberEX.text = string.isEmpty(oldMyRankInfo.hurt) and "--" or valueOld
        self.TxtNumberNow.text = string.isEmpty(newMyRankInfo.hurt) and "--" or valueNew
        if not IsNull(self.ImgUP) then
            KTool.SetActive(self.ImgUP.gameObject, valueNew > 0 and valueNew > valueOld)
        end
    end
end

function UIBattleEndWorldBoss:SetClubBossNodeInfo()
    local showData = BattleEndMgr.showData
    if IsNull(showData) or (not isSet(showData, "response")) then return end

    if checkNumber(showData.isPassed) == 0 then
        KTool.SetActive(self.Root_WorldBoss.gameObject,false)
        return
    end

    --- 节点激活状态
    KTool.SetActive(self.Root_WorldBoss.gameObject,true)
    KTool.SetActive(self.TxtNow.gameObject, true)
    KTool.SetActive(self.TxtHistory.gameObject, false)
    KTool.SetActive(self.TxtQuestLocked.gameObject, false) -- 活动结束提示
    KTool.SetActive(self.ImgUP.gameObject, false)
    --- 分数文本组件赋值
    local dataResponse = showData.response
    self.TxtNumberNow.text = math.modf(checkNumber(dataResponse.hurt))
end

---设置怪谈事件Boss结算节点显示
function UIBattleEndWorldBoss:SetActivityCrisisBossNodeInfo()
    local showData = BattleEndMgr.showData
    if IsNull(showData) or (not isSet(showData, "response")) then return end

    if checkNumber(showData.isPassed) == 0 then
        KTool.SetActive(self.Root_WorldBoss.gameObject,false)
        return
    end

    --- 节点激活状态
    KTool.SetActive(self.Root_WorldBoss.gameObject,true)

    CfUtils.SetUISwitchText(self.TxtNow.gameObject,2)
    KTool.SetActive(self.TxtNow.gameObject, true)

    CfUtils.SetUISwitchText(self.TxtHistory.gameObject,2)
    KTool.SetActive(self.TxtHistory.gameObject, true)


    local dataResponse = showData.response
    local oldMyRankInfo = checkTable(dataResponse.oldMyRankInfo) -- 返回数据 历史
    local newMyRankInfo = checkTable(dataResponse.newMyRankInfo) -- 返回数据 当前
    --- 分数更新 Icon 提示
    local valueOld = math.modf(checkNumber(oldMyRankInfo.hurt))
    local valueNew = math.modf(checkNumber(newMyRankInfo.hurt))
    self.TxtNumberEX.text = string.isEmpty(oldMyRankInfo.hurt) and "--" or valueOld
    self.TxtNumberNow.text = string.isEmpty(newMyRankInfo.hurt) and "--" or valueNew

    KTool.SetActive(self.TxtQuestLocked.gameObject, false) -- 活动结束提示
    KTool.SetActive(self.ImgUP.gameObject, false)

    if not IsNull(self.ImgUP) then
        KTool.SetActive(self.ImgUP.gameObject, valueNew > 0 and valueNew > valueOld)
    end

end



